var code = String(input.code || "");
var language = String(input.language || "unknown");
var lines = code.split(/\r?\n/);
var checks = [];
if (lines.length > 300) checks.push("文件超过 300 行，考虑拆分");
if (code.indexOf("TODO") >= 0 || code.indexOf("FIXME") >= 0) checks.push("存在 TODO/FIXME 标记");
if (code.indexOf("console.log") >= 0) checks.push("残留调试输出 console.log");
if (code.indexOf("password") >= 0 || code.indexOf("secret") >= 0 || code.indexOf("token") >= 0) checks.push("可能存在硬编码凭据");
if (checks.length === 0) checks.push("未发现明显问题（启发式检查，仅供参考）");
var md = "# 代码审查清单（" + language + "）\n\n" + checks.map(function (c) { return "- " + c; }).join("\n");
return { markdown: md, checks: checks };
